function validate([cards]) {
  if (!Array.isArray(cards) || cards.length !== 4) return 'cards must hold exactly 4 numbers.';
  if (cards.some(v => !Number.isInteger(v) || v < 1 || v > 9)) return 'Each card is a whole number from 1 to 9.';
  return null;
}

