function judgePoint24(cards) {
  const EPSILON = 1e-6;

  function solve(numbers) {
    if (numbers.length === 1) {
      return Math.abs(numbers[0] - 24) < EPSILON;
    }
    for (let i = 0; i < numbers.length; i++) {
      for (let j = i + 1; j < numbers.length; j++) {
        const rest = numbers.filter((_, k) => k !== i && k !== j);
        const a = numbers[i];
        const b = numbers[j];
        const options = [a * b, a + b, a - b, b - a];
        if (Math.abs(b) > EPSILON) {
          options.push(a / b);
        }
        if (Math.abs(a) > EPSILON) {
          options.push(b / a);
        }
        for (const value of options) {
          if (solve([value, ...rest])) {
            return true;
          }
        }
      }
    }
    return false;
  }

  return solve(cards);
}

