function judgePoint24(cards) {
  // Exact fractions: for every subset of cards, list every value its cards can make, then look for 24 in the full set.
  const gcd = (x, y) => (y === 0 ? Math.abs(x) : gcd(y, x % y));
  const make = (n, d) => {
    if (d < 0) { n = -n; d = -d; }
    const g = gcd(n, d) || 1;
    return [n / g, d / g];
  };
  const values = new Map();
  for (let mask = 1; mask < 16; mask++) {
    const found = new Map();
    const bits = [0, 1, 2, 3].filter(b => mask & (1 << b));
    if (bits.length === 1) found.set(cards[bits[0]] + '/1', [cards[bits[0]], 1]);
    for (let part = (mask - 1) & mask; part > 0; part = (part - 1) & mask) {
      for (const [n1, d1] of values.get(part).values()) {
        for (const [n2, d2] of values.get(mask ^ part).values()) {
          const results = [make(n1 * d2 + n2 * d1, d1 * d2), make(n1 * d2 - n2 * d1, d1 * d2), make(n1 * n2, d1 * d2)];
          if (n2 !== 0) results.push(make(n1 * d2, d1 * n2));
          for (const [n, d] of results) found.set(n + '/' + d, [n, d]);
        }
      }
    }
    values.set(mask, found);
  }
  return values.get(15).has('24/1');
}

