function generate(rand, size) {
  // Every input has exactly four cards; small inputs lean on repeated cards, which are often unsolvable.
  const top = size === 'small' && rand() < 0.4 ? 3 : 9;
  return [Array.from({ length: 4 }, () => 1 + Math.floor(rand() * top))];
}
